class Performance
{
private:
    long double weight = 0;
    long double reps = 0;

public:
    Performance() noexcept {};
    Performance(long double init_weight, long double init_reps) noexcept : weight(init_weight), reps(init_reps) {}
    Performance(std::nullptr_t init_weight, long double init_reps, Performance baseline) noexcept : weight(baseline.complete_weight(init_reps)), reps(init_reps) {}
    Performance(long double init_weight, std::nullptr_t init_reps, Performance baseline) noexcept : weight(init_weight), reps(baseline.complete_reps(init_weight)) {}

    long double get_weight() const noexcept { return this->weight; }
    long double get_reps() const noexcept { return this->reps; }

    bool operator<(Performance p) const noexcept { return this->weight < p.weight; }

    // change weight while keeping effort constant i.e reps performed / reps possible
    long double shift_weight(Performance baseline, long double new_weight) noexcept
    {
        this->reps = (this->reps / baseline.complete_reps(this->weight)) * baseline.complete_reps(new_weight);
        this->weight = new_weight;
        
        return this->reps;
    }

    long double increment_reps() noexcept { return ++this->reps; }
    long double round_reps() noexcept { return this->reps = std::roundl(this->reps); }
    long double floor_reps() noexcept { return this->reps = std::floor(this->reps + 0.001); }
    long double reduce_reps(long double reduction) noexcept { return this->reps -= reduction; }
    long double double_reps() noexcept { return this->reps *= 2; }

    long double estimate_rm() const noexcept
    {
        long double max_weight;

        if (this->reps <= 8)
        {
            max_weight = this->weight / (1.0278 - (0.0278 * this->reps));
        }
        else if (this->reps >= 10)
        {
            max_weight = this->weight * (1 + ((this->reps) / 30.0));
        }
        else
        {
            max_weight = ((this->weight * (10 - this->reps)) / (2 * (1.0278 - (0.0278 * this->reps))) + this->weight + ((this->weight * (-75 + (8 * this->reps))) / 15) - ((this->weight * this->reps * (10 - this->reps)) / 60));
        }

        return max_weight;
    }

    static long double percent_change(Performance a, Performance b) { return (b.estimate_rm() - a.estimate_rm()) / a.estimate_rm(); }
    
    long double complete_weight(long double target_reps) const noexcept
    {
        long double deduced_weight;
        long double brzycki_est = estimate_rm() * (1.0278 - (0.0278 * target_reps));
        long double epley_est = (30 * estimate_rm()) / (30 + target_reps);

        if (target_reps == this->reps)
        {
            deduced_weight = this->weight;
        } 
        else if (target_reps <= 8)
        {
            deduced_weight = brzycki_est;
        }
        else if (target_reps >= 10)
        {
            deduced_weight = epley_est;
        }
        else
        {
            deduced_weight = ((estimate_rm() * (1.0278 - (0.0278 * target_reps))) * 0.5) + (((30 * estimate_rm()) / (30 + target_reps)) * 0.5);
        }

        return deduced_weight;
    }

    long double complete_reps(long double target_weight) const noexcept
    {
        long double deduced_reps;
        long double brzycki_threshold = estimate_rm() * 0.8054;
        long double epley_threshold = estimate_rm() * 0.75;
        long double rev_brzycki_est = -(((target_weight / estimate_rm()) - 1.0278) / 0.0278);
        long double rev_epley_est = (((30 * estimate_rm()) / target_weight) - 30);

        if (target_weight == this->weight)
        {
            deduced_reps = this->reps;
        }
        // The weight whereafter any heavier would be less than 8 reps
        else if (target_weight >= brzycki_threshold)
        {
            deduced_reps = rev_brzycki_est;
        }
        // The weight whereafter any lighter would be more than 10 reps
        else if (target_weight <= epley_threshold) 
        {
            deduced_reps = rev_epley_est;
        }
        else
        {       
            // Not an exact solution
            deduced_reps = ((target_weight / brzycki_threshold) - 1.226244224) / -0.02953801791;
        }
        
        return deduced_reps;
    }
};

std::ostream& operator<<(std::ostream& os, Performance p) 
{ 
    return os << p.get_weight() << "lb x " << p.get_reps();
}

